    if($a==='cron_kick'){Cron::kick(true);flash('Scheduler started.');}
    if($a==='repo'){Settings::set('update_repo',trim($_POST['repo'])?:Updater::REPO);Settings::set('update_mode',($_POST['mode']??'')==='commit'?'commit':'release');Settings::set('update_branch',trim($_POST['branch'])?:'main');if(($_POST['token']??'')!=='')Settings::set('github_token',trim($_POST['token']));Updater::check(true);flash('Update source saved.');}
  }catch(Throwable $e){flash(e($e->getMessage()),'err');}
  redirect(url('updates'));}
if(isset($_GET['migrate'])){$ran=Migrator::run();flash($ran?'Database updated: '.e(implode(', ',$ran)):'Database is up to date.');redirect(url('updates'));}
