<div class="g2"><div class="card hero"><div class="card-h"><h3><?=icon('refresh')?>Version</h3><form method="post"><?=csrf_field()?><input type="hidden" name="a" value="check"><button class="btn btn-sm"><?=icon('refresh')?>Check now</button></form></div><div class="ver"><div><span>Installed</span><b>v<?=e(APP_VERSION)?></b></div><div><span><?=$u['mode']==='commit'?'Latest commit':'Latest release'?></span><b><?=$u['latest']?($u['mode']==='commit'?'#'.e($u['latest']):'v'.e($u['latest'])):'—'?></b></div></div><p class="sm muted mt0">Update channel: <b><?=$u['mode']==='commit'?'Latest commit':'Releases only'?></b> · <a class="lnk" href="https://github.com/<?=e(Updater::repo())?>" target="_blank" rel="noopener"><?=e(Updater::repo())?></a><?=$u['mode']==='commit'?' · branch '.e(Updater::branch()).(!empty($u['version'])?' (version.json v'.e($u['version']).')':''):''?></p><?php if(!empty($u['error'])):?><div class="al al-warn"><?=icon('alert')?><span><?=e($u['error'])?></span></div><?php endif?><?php if($pend):?><div class="al al-warn"><?=icon('alert')?><span>Database update pending (<?=e(implode(', ',$pend))?>). <a href="<?=url('updates',['migrate'=>1])?>">Run it now</a></span></div><?php endif?><?php if(!empty($u['available'])):?><div class="al al-ok"><?=icon('zap')?><span><b><?=$u['mode']==='commit'?'New commit available: #'.e($u['latest']).(empty($u['installed_sha'])?' (installed commit unknown)':''):'Update available: v'.e($u['latest'])?></b><?=$u['date']?' · '.e($u['date']):''?></span></div><?php if($u['notes']):?><ul class="ul"><?php foreach((array)$u['notes'] as $n):?><li><?=e($n)?></li><?php endforeach?></ul><?php endif?><form method="post" onsubmit="this.querySelector('button').disabled=true;this.querySelector('button').innerHTML='Updating… please wait';return confirm('Install <?=$u['mode']==='commit'?'commit #':'v'?><?=e($u['latest'])?> now? Changed files are backed up to storage/backups first. Your database, settings, reports and uploads stay untouched.')"><?=csrf_field()?><input type="hidden" name="a" value="apply"><button class="btn btn-y btn-b"><?=icon('download')?>Update now</button></form><?php elseif($u['latest']):?><p class="muted"><?=icon('check')?> You are on the latest version. Last checked <?=ago(date('Y-m-d H:i:s',$u['at']))?>.</p><?php endif?></div>
<form method="post" class="card frm"><?=csrf_field()?><input type="hidden" name="a" value="repo"><div class="card-h"><h3>Update source</h3></div><label>What to install<select name="mode"><option value="release" <?=Updater::mode()==='release'?'selected':''?>>Releases only – stable versions published on GitHub (recommended)</option><option value="commit" <?=Updater::mode()==='commit'?'selected':''?>>Latest commit – newest code on the branch, as soon as it is pushed</option></select><small>Releases only: updates appear when a new release (tag like v1.1.0) is published. Latest commit: every push to the branch is offered as an update.</small></label><label>GitHub repository<input name="repo" value="<?=e(Updater::repo())?>" placeholder="<?=Updater::REPO?>"></label><label>Branch<input name="branch" value="<?=e(setting('update_branch','main'))?>"></label><label>GitHub token (only for private repos)<input type="password" name="token" placeholder="<?=setting('github_token')?'•••••••• saved':'ghp_… (read-only Contents permission)'?>"><small>Create at github.com → Settings → Developer settings → Fine-grained tokens → Repository access: this repo → Contents: Read-only.</small></label><button class="btn">Save</button></form></div>
